INSERT INTO messages (message_id, user_id, chat_id, "timestamp", message_text, photo_file_id, photo_file_size, urls, edit_date, content_hash, photo_local_path, photo_thumbnail_path, deleted_at, deletion_source, reply_to_message_id, media_type, media_file_id, media_file_size, media_file_name, media_mime_type, media_local_path, media_duration, content_check_skip_reason, similarity_hash) VALUES (222716, 9058402298095, -100026957614982, '2026-04-22 08:38:26.314616+00', 'I''m sharing this for anyone who has an interest in cancer research outside the standard chemotherapy/immunotherapy box, or who follows medical regulatory cases in Canada.
Dr. William Makis is a Canadian physician (radiologist with oncology experience) who has become a polarizing figure over the last couple of years. On one hand, he''s known for his public discussions of repurposed medications in oncology – drugs like fenbendazole (a veterinary antiparasitic), ivermectin (an antiparasitic with some controversial COVID history), doxycycline (an antibiotic), and mebendazole (another antiparasitic). He often cites preclinical studies, case reports, and what he calls "signal detection" from real-world data. This has earned him both a dedicated following and sharp criticism from mainstream oncology groups.
On the other hand, Dr. Makis has been involved in ongoing regulatory and legal proceedings in Canada that have directly impacted his medical practice. The relevant provincial regulatory authorities have publicly documented these matters – they include hearings, restrictions, and appeals. The cases are still active, and new developments come out periodically.
He recently launched a Telegram channel, which he says will serve several functions: sharing public statements and updates about his work and legal situation, discussing emerging and experimental cancer research in an informational context (not as medical advice), providing access to educational materials and publicly available research discussions, and communicating transparently with individuals who follow his work. He emphasizes that the group is intended for open discussion and awareness, not as a substitute for professional medical care.
If you''re the kind of person who likes to follow unconventional medical researchers, or who tracks Canadian medical legal cases, or who just wants to hear directly from a controversial figure without media filtering, this might be worth a look.
Here''s the link to his Telegram channel: canonical-spam.test/+C3K-79z-VxRjZjk5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 08:38:31.161639+00', 'moderation_action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL);
